async function exaSearch(
	built: BuiltSearchQuery,
	count: number,
	type: NonNullable<StructuredSearchArgs["type"]>,
	includeText: boolean,
	apiKey: string,
	signal?: AbortSignal,
): Promise<SearchResult[]> {
	const body: Record<string, unknown> = {
		query: built.query,
		numResults: Math.min(Math.max(count, 1), 10),
		type,
		contents: includeText
			? { text: { maxCharacters: 1000 }, highlights: { maxCharacters: 300 } }
			: { highlights: { maxCharacters: 300 } },
	};

	if (built.site) body.includeDomains = [built.site];

	const resp = await fetch("https://api.exa.ai/search", {
		method: "POST",
		signal,
		headers: {
			"Content-Type": "application/json",
			"x-api-key": apiKey,
		},
		body: JSON.stringify(body),
	});

	if (!resp.ok) {
		const text = await resp.text();
		throw new Error(`Exa API ${resp.status}: ${text.slice(0, 500)}`);
	}

	const data = (await resp.json()) as ExaResponse;
	return (data.results ?? [])
		.filter((item) => item.url)
		.map((item) => {
			const snippet =
				item.summary ||
				item.highlights?.filter(Boolean).join(" … ") ||
				item.text?.replace(/\s+/g, " ").slice(0, 500) ||
				"";

			return {
				title: item.title || item.url || "Untitled",
				url: item.url!,
				snippet,
				publishedDate: item.publishedDate,
				author: item.author,
				score: item.score,
			};
		});
}

function formatResults(results: SearchResult[]): string {
	if (results.length === 0) return "No results found.";
	return results
		.map((r, i) => {
			const meta = [r.publishedDate, r.author].filter(Boolean).join(" | ");
			return [
				`${i + 1}. ${r.title}`,
				`   ${r.url}`,
				meta ? `   ${meta}` : undefined,
				r.snippet ? `   ${r.snippet}` : undefined,
			]
				.filter(Boolean)
				.join("\n");
		})
		.join("\n\n");
}

