import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { StringEnum } from "@mariozechner/pi-ai";
import { Type } from "typebox";
import { Text } from "@mariozechner/pi-tui";
import * as fs from "node:fs";
import * as path from "node:path";

interface SearchResult {
	title: string;
	url: string;
	snippet: string;
	publishedDate?: string;
	author?: string;
}

interface StructuredSearchArgs {
	query?: string;
	exactPhrases?: string[];
	excludeTerms?: string[];
	site?: string;
	count?: number;
	type?: "auto" | "neural" | "fast" | "instant" | "deep" | "deep-reasoning";
	includeText?: boolean;
}

interface BuiltSearchQuery {
	query: string;
	baseQuery?: string;
	exactPhrases: string[];
	excludeTerms: string[];
	site?: string;
}

interface ExaResponse {
	results?: Array<{
		title?: string;
		url?: string;
		text?: string;
		summary?: string;
		highlights?: string[];
		publishedDate?: string;
		author?: string;
	}>;
}

const EXT_DIR = path.dirname(new URL(import.meta.url).pathname);
const AUTH_PATH = path.join(EXT_DIR, "auth.json");

function loadApiKey(): string | null {
	const envKey = process.env.EXA_API_KEY ?? process.env.EXA_SEARCH_API_KEY;
	if (envKey) return envKey;

	if (!fs.existsSync(AUTH_PATH)) return null;
	try {
		const config = JSON.parse(fs.readFileSync(AUTH_PATH, "utf-8"));
		return (config.exa_api_key as string) || null;
	} catch {
		return null;
	}
}

function stripWrappingQuotes(value: string): string {
	return value.length >= 2 && value.startsWith('"') && value.endsWith('"')
		? value.slice(1, -1).trim()
		: value;
}

function cleanItems(values?: string[]): string[] {
	return (values ?? [])
		.map((value) => stripWrappingQuotes(value.trim().replace(/\s+/g, " ")))
		.filter(Boolean);
}

function cleanQuery(value?: string): string | undefined {
	if (typeof value !== "string") return undefined;
	const cleaned = value.trim().replace(/\s+/g, " ");
	return cleaned || undefined;
}

function normalizeSite(site?: string): string | undefined {
	if (typeof site !== "string") return undefined;

	let value = site.trim().replace(/^site:/i, "").trim();
	if (!value) return undefined;

	try {
		const candidate = /^[a-z]+:\/\//i.test(value) ? value : `https://${value}`;
		const url = new URL(candidate);
		if (url.hostname) value = url.hostname;
	} catch {}

	return value.replace(/\/+$/, "") || undefined;
}

function quoteForSearch(value: string): string {
	return `"${value.replace(/"/g, '\\"')}"`;
}

function buildSearchQuery(args: StructuredSearchArgs): BuiltSearchQuery {
	const baseQuery = cleanQuery(args.query);
	const exactPhrases = cleanItems(args.exactPhrases);
	const excludeTerms = cleanItems(args.excludeTerms);
	const site = normalizeSite(args.site);

	if (!baseQuery && exactPhrases.length === 0) {
		throw new Error("At least one of 'query' or 'exactPhrases' is required.");
	}

	const parts: string[] = [];
	if (baseQuery) parts.push(baseQuery);
	for (const phrase of exactPhrases) parts.push(quoteForSearch(phrase));
	for (const term of excludeTerms) {
		parts.push(`-${term.includes(" ") ? quoteForSearch(term) : term}`);
	}

	return {
		query: parts.join(" "),
		baseQuery,
		exactPhrases,
		excludeTerms,
		site,
	};
}

async function exaSearch(
	built: BuiltSearchQuery,
	count: number,
	type: NonNullable<StructuredSearchArgs["type"]>,
	includeText: boolean,
	apiKey: string,
	signal?: AbortSignal,
): Promise<SearchResult[]> {
	const body: Record<string, unknown> = {
		query: built.query,
		numResults: Math.min(Math.max(count, 1), 10),
		type,
		contents: includeText
			? { text: { maxCharacters: 1000 }, highlights: { maxCharacters: 300 } }
			: { highlights: { maxCharacters: 300 } },
	};

	if (built.site) body.includeDomains = [built.site];

	const resp = await fetch("https://api.exa.ai/search", {
		method: "POST",
		signal,
		headers: {
			"Content-Type": "application/json",
			"x-api-key": apiKey,
		},
		body: JSON.stringify(body),
	});

	if (!resp.ok) {
		const errorBody = await resp.text();
		throw new Error(`Exa API ${resp.status}: ${errorBody.slice(0, 500)}`);
	}

	const data = (await resp.json()) as ExaResponse;
	return (data.results ?? [])
		.filter((item) => item.url)
		.map((item) => ({
			title: item.title || item.url || "Untitled",
			url: item.url!,
			snippet:
				item.summary ||
				item.highlights?.filter(Boolean).join(" … ") ||
				item.text?.replace(/\s+/g, " ").slice(0, 500) ||
				"",
			publishedDate: item.publishedDate,
			author: item.author,
		}));
}

function formatResults(results: SearchResult[]): string {
	if (results.length === 0) return "No results found.";
	return results
		.map((r, i) => {
			const meta = [r.publishedDate, r.author].filter(Boolean).join(" | ");
			return [
				`${i + 1}. ${r.title}`,
				`   ${r.url}`,
				meta ? `   ${meta}` : undefined,
				r.snippet ? `   ${r.snippet}` : undefined,
			]
				.filter(Boolean)
				.join("\n");
		})
		.join("\n\n");
}

export default function (pi: ExtensionAPI) {
	pi.registerTool({
		name: "web_search",
		label: "Web Search",
		description:
			"Search the web using Exa API. Build one search per call from a base query string, exact phrases, exclusions, and an optional site/domain. Returns title, URL, and snippet.",
		promptSnippet:
			"Search the web using Exa via a query string plus optional exactPhrases, excludeTerms, and site. Use one tool call per search angle.",
		promptGuidelines: [
			"Use exactPhrases for exact phrase matching instead of embedding quote marks inside the main query string.",
			"Use one web_search tool call per search angle instead of batching multiple searches into one call.",
		],

		parameters: Type.Object({
			query: Type.Optional(
				Type.String({
					description:
						"Base search query as a normal string. Prefer this for the main search wording.",
				}),
			),
			exactPhrases: Type.Optional(
				Type.Array(Type.String(), {
					description:
						"Exact phrases to match. Each item is added to the Exa query in quotes.",
				}),
			),
			excludeTerms: Type.Optional(
				Type.Array(Type.String(), {
					description:
						"Terms or phrases to exclude. Multi-word items are excluded as exact phrases.",
				}),
			),
			site: Type.Optional(
				Type.String({
					description:
						"Optional site/domain restriction, such as example.com or a full URL.",
				}),
			),
			count: Type.Optional(
				Type.Number({
					description: "Number of results to return (default: 5, max: 10)",
					minimum: 1,
					maximum: 10,
				}),
			),
			type: Type.Optional(
				StringEnum(["auto", "neural", "fast", "instant", "deep", "deep-reasoning"] as const, {
					description: "Exa search type. Defaults to auto.",
				}),
			),
			includeText: Type.Optional(
				Type.Boolean({
					description:
						"Include up to 1000 characters of page text for each result. Defaults to false.",
				}),
			),
		}),

		async execute(_toolCallId, params: StructuredSearchArgs, signal) {
			const apiKey = loadApiKey();
			if (!apiKey) {
				throw new Error(
					`Missing Exa API key. Set EXA_API_KEY, or create ${AUTH_PATH} with { "exa_api_key": "..." }.` ,
				);
			}

			const built = buildSearchQuery(params);
			const count = params.count ?? 5;
			const type = params.type ?? "auto";
			const includeText = params.includeText ?? false;
			const results = await exaSearch(built, count, type, includeText, apiKey, signal);

			return {
				content: [{ type: "text" as const, text: formatResults(results) }],
				details: {
					provider: "exa",
					composedQuery: built.query,
					query: built.baseQuery,
					exactPhrases: built.exactPhrases,
					excludeTerms: built.excludeTerms,
					site: built.site,
					type,
					includeText,
					resultCount: results.length,
				},
			};
		},

		renderCall(args, theme, context) {
			const text = (context.lastComponent as Text | undefined) ?? new Text("", 0, 0);
			const { count, type, includeText, ...searchArgs } = args as StructuredSearchArgs;

			try {
				const built = buildSearchQuery(searchArgs);
				const display = built.query.length > 70 ? built.query.slice(0, 67) + "..." : built.query;
				const lines = [
					theme.fg("toolTitle", theme.bold("exa search ")) + theme.fg("accent", `"${display}"`),
				];
				if (count && count !== 5) lines.push(theme.fg("dim", `  count: ${count}`));
				if (type && type !== "auto") lines.push(theme.fg("dim", `  type: ${type}`));
				if (includeText) lines.push(theme.fg("dim", "  include text"));
				text.setText(lines.join("\n"));
				return text;
			} catch {
				text.setText(theme.fg("toolTitle", theme.bold("exa search ")) + theme.fg("error", "(invalid query)"));
				return text;
			}
		},

		renderResult(result, { expanded, isPartial }, theme, context) {
			const text = (context.lastComponent as Text | undefined) ?? new Text("", 0, 0);

			if (isPartial) {
				text.setText(theme.fg("warning", "Searching Exa…"));
				return text;
			}

			if (context.isError) {
				const msg = result.content.find((c) => c.type === "text")?.text || "Error";
				text.setText(theme.fg("error", msg));
				return text;
			}

			const details = result.details as { composedQuery?: string; resultCount?: number };
			const status = theme.fg("success", `${details?.resultCount ?? 0} Exa results`);
			if (!expanded) {
				text.setText(status);
				return text;
			}

			const content = result.content.find((c) => c.type === "text")?.text || "";
			const preview = content.length > 500 ? content.slice(0, 500) + "..." : content;
			const queryLine = details?.composedQuery ? theme.fg("dim", `query: ${details.composedQuery}`) : "";
			text.setText([status, queryLine, theme.fg("dim", preview)].filter(Boolean).join("\n"));
			return text;
		},
	});
}

