			}

			const count = params.count ?? 5;
			const built = buildSearchQuery(params);
			const results = await googleSearch(
				built.query,
				count,
				creds.apiKey,
				creds.cseId,
				signal,
			);

			return {
				content: [
					{
						type: "text" as const,
						text: formatResults(results),
					},
				],
				details: {
					composedQuery: built.query,
					query: built.baseQuery,
					exactPhrases: built.exactPhrases,
